import type { TokenApprovalTransactionStep } from 'uniswap/src/features/transactions/steps/approve'
import { OnChainTransactionFields, OnChainTransactionFieldsBatched, TransactionStepType } from 'uniswap/src/features/transactions/steps/types'
import { ValidatedTransactionRequest } from 'uniswap/src/features/transactions/swap/utils/trade'

export interface DecreasePositionTransactionStep extends OnChainTransactionFields {
  // Doesn't require permit
  type: TransactionStepType.DecreasePositionTransaction
}

export interface DecreasePositionTransactionStepBatched extends OnChainTransactionFieldsBatched {
  type: TransactionStepType.DecreasePositionTransactionBatched
  fallbackSteps?: DecreasePositionFallbackStep[]
}

export function createDecreasePositionStep(txRequest: ValidatedTransactionRequest): DecreasePositionTransactionStep {
  return {
    type: TransactionStepType.DecreasePositionTransaction,
    txRequest,
  }
}

export function createDecreasePositionStepBatched(
  batchedTxRequests: ValidatedTransactionRequest[],
  fallbackSteps?: DecreasePositionFallbackStep[],
): DecreasePositionTransactionStepBatched {
  return {
    type: TransactionStepType.DecreasePositionTransactionBatched,
    batchedTxRequests,
    fallbackSteps,
  }
}

export type DecreasePositionFallbackStep = TokenApprovalTransactionStep | DecreasePositionTransactionStep
