// Helper to convert formatted reserve to raw amount for Pair creation
function parseReserveToRaw(reserve: string, decimals: number): string {
  // Subgraph returns formatted amounts (e.g. "33843.701"), convert to raw wei
  // Handle scientific notation (e.g., "1.234e+21")
  if (reserve.includes('e') || reserve.includes('E')) {
    try {
      const num = parseFloat(reserve)
      if (!isFinite(num) || num < 0) {
        console.warn('Invalid scientific notation reserve:', reserve)
        return '0'
      }
      // Convert to fixed decimal string to avoid precision loss
      const fixedStr = num.toFixed(decimals)
      return parseReserveToRaw(fixedStr, decimals)
    } catch (error) {
      console.warn('Failed to parse scientific notation:', reserve, error)
      return '0'
    }
  }
  
  // Use string manipulation to avoid scientific notation issues with large numbers
  const parts = reserve.split('.')
  const wholePart = parts[0] || '0'
  const fractionalPart = parts[1] || ''

  // Calculate how many decimal places we need to shift
  const fractionalDigits = fractionalPart.length
  const zerosToAdd = Math.max(0, decimals - fractionalDigits)

  // Construct the raw amount as a string
  const rawAmount = wholePart + fractionalPart + '0'.repeat(zerosToAdd)

  // Remove leading zeros but keep at least one digit
  return rawAmount.replace(/^0+/, '') || '0'
}

// V2 Quote Logic
export async function getV2Quote(params: V2QuoteParams): Promise<V2OnchainBestRoute | null> {
  const { currencyIn, currencyOut, inputAmount, tradeType, poolData, effectiveChainId, routerAddress, factoryAddress, ethersProvider } = params
  
  
  try {
    // Only support exact input on-chain quoting for now
    if (tradeType !== TradeType.EXACT_INPUT) {
      return null
    }

    const tokenInAddress = (currencyIn.isToken ? currencyIn.address : currencyIn.wrapped.address).toLowerCase()
    const tokenOutAddress = (currencyOut.isToken ? currencyOut.address : currencyOut.wrapped.address).toLowerCase()

    // Lookup by (a,b,stable)
    const keyFor = (a: string, b: string, stable: boolean) => `${a}-${b}-${stable ? 's' : 'v'}`
    const poolMap = new Map<string, any>()
    for (const p of poolData) {
      const a = p.token0.id.toLowerCase()
      const b = p.token1.id.toLowerCase()
      const s = Boolean(p.stable)
      poolMap.set(keyFor(a, b, s), p)
      poolMap.set(keyFor(b, a, s), p)
    }

    const makePair = (p: any): Pair | null => {
      try {
        const t0 = new Token(effectiveChainId, p.token0.id, parseInt(p.token0.decimals), p.token0.symbol, p.token0.name)
        const t1 = new Token(effectiveChainId, p.token1.id, parseInt(p.token1.decimals), p.token1.symbol, p.token1.name)
        const r0 = parseReserveToRaw(p.reserve0, t0.decimals)
        const r1 = parseReserveToRaw(p.reserve1, t1.decimals)

        // Debug logging for reserve data
        console.log(`[V2 Pair Debug] Pool: ${t0.symbol}/${t1.symbol}`)
        console.log(`  Subgraph reserve0: ${p.reserve0} (${t0.symbol})`)
        console.log(`  Subgraph reserve1: ${p.reserve1} (${t1.symbol})`)
        console.log(`  Parsed raw r0: ${r0}`)
        console.log(`  Parsed raw r1: ${r1}`)
        console.log(`  Token0 decimals: ${t0.decimals}, Token1 decimals: ${t1.decimals}`)

        if (r0 === '0' || r1 === '0') return null
        const ca0 = CurrencyAmount.fromRawAmount(t0, r0)
        const ca1 = CurrencyAmount.fromRawAmount(t1, r1)
        const pair = new Pair(ca0, ca1)

        // Log the resulting price
        console.log(`  Pair price: 1 ${pair.token0.symbol} = ${pair.token0Price.toSignificant(6)} ${pair.token1.symbol}`)
        console.log(`  Pair price: 1 ${pair.token1.symbol} = ${pair.token1Price.toSignificant(6)} ${pair.token0.symbol}`)

        ;(pair as any).actualAddress = p.id
        ;(pair as any).stable = Boolean(p.stable)
        return pair
      } catch (err) {
        console.error(`[V2 Pair Debug] Failed to create pair:`, err)
        return null
      }
    }

    type Hop = { from: string; to: string; stable: boolean; factory: string }
    type Candidate = { path: string[]; stableFlags: boolean[]; hops: Hop[]; pairs: Pair[] }
    const candidates: Candidate[] = []
    const seen = new Set<string>()
    const addCandidate = (path: string[], stables: boolean[], pools: any[]) => {
      const key = `${path.join('>')}|${stables.map((s) => (s ? 's' : 'v')).join('>')}`
      if (seen.has(key)) return
      const pairs: Pair[] = []
      for (const p of pools) {
        const pr = makePair(p)
        if (!pr) return
        pairs.push(pr)
      }
      const hops: Hop[] = []
      for (let i = 0; i < path.length - 1; i++) {
        hops.push({ from: path[i], to: path[i + 1], stable: stables[i], factory: factoryAddress })
      }
      candidates.push({ path, stableFlags: stables, hops, pairs })
      seen.add(key)
    }

    // Direct pools (both variants)
    for (const s of [false, true]) {
      const p = poolMap.get(keyFor(tokenInAddress, tokenOutAddress, s))
      if (p) addCandidate([tokenInAddress, tokenOutAddress], [s], [p])
    }

    // Two-hop via intermediaries
    const connectors = getCommonIntermediaries(effectiveChainId).map((x) => x.toLowerCase()).filter((x) => x !== tokenInAddress && x !== tokenOutAddress)
    for (const mid of connectors) {
      for (const s1 of [false, true]) {
        for (const s2 of [false, true]) {
          const p1 = poolMap.get(keyFor(tokenInAddress, mid, s1))
          const p2 = poolMap.get(keyFor(mid, tokenOutAddress, s2))
          if (p1 && p2) addCandidate([tokenInAddress, mid, tokenOutAddress], [s1, s2], [p1, p2])
        }
      }
    }

    // Three-hop via two intermediaries (max hops = 3)
    if (connectors.length > 1) {
      for (let i = 0; i < connectors.length; i++) {
        const mid1 = connectors[i]
        for (let j = 0; j < connectors.length; j++) {
          const mid2 = connectors[j]
          if (mid1 === mid2) continue
          if (mid1 === tokenInAddress || mid1 === tokenOutAddress) continue
          if (mid2 === tokenInAddress || mid2 === tokenOutAddress) continue
          for (const s1 of [false, true]) {
            for (const s2 of [false, true]) {
              for (const s3 of [false, true]) {
                const p1 = poolMap.get(keyFor(tokenInAddress, mid1, s1))
                const p2 = poolMap.get(keyFor(mid1, mid2, s2))
                const p3 = poolMap.get(keyFor(mid2, tokenOutAddress, s3))
                if (p1 && p2 && p3) {
                  addCandidate(
                    [tokenInAddress, mid1, mid2, tokenOutAddress],
                    [s1, s2, s3],
                    [p1, p2, p3],
                  )
                }
              }
            }
          }
        }
      }
    }

    if (candidates.length === 0) {
      return null
    }

    const router = new Contract(routerAddress, V2_ROUTER_ABI as any, ethersProvider)
    const amountInRaw = inputAmount.quotient.toString()

    // Prefer batching via Multicall3 if provided
    let results: { c: Candidate; out: string }[] = []
    const multicall = (params as any).multicallContract as Contract | undefined
    if (multicall && candidates.length > 1) {
      const calls = candidates.map((c) => {
        const cd = router.interface.encodeFunctionData('getAmountsOut', [amountInRaw, c.hops])
        return { target: router.address, callData: cd }
      })
      try {
        const timeoutPromise = new Promise((_, reject) => setTimeout(() => reject(new Error('Multicall timeout after 30s')), 30000))
        const multicallPromise = multicall.callStatic.tryAggregate(false, calls)
        const res: any[] = (await Promise.race([multicallPromise, timeoutPromise])) as any[]
        res.forEach((r, i) => {
          if (!r?.success) {
            results.push({ c: candidates[i], out: '0' })
            return
          }
          try {
            const decoded = router.interface.decodeFunctionResult('getAmountsOut', r.returnData)
            const amounts: ethers.BigNumber[] = decoded[0]
            const out = amounts[amounts.length - 1].toString()
            results.push({ c: candidates[i], out })
          } catch {
            results.push({ c: candidates[i], out: '0' })
          }
        })
      } catch {
        // Fallback to parallel direct calls
      }
    }

    if (results.length === 0) {
      results = await Promise.all(
        candidates.map(async (c) => {
          try {
            const amounts: ethers.BigNumber[] = await router.getAmountsOut(amountInRaw, c.hops)
            const out = amounts[amounts.length - 1].toString()
            return { c, out }
          } catch {
            return { c, out: '0' }
          }
        }),
      )
    }

    let best: { c: Candidate; out: string } | null = null
    for (const r of results) {
      if (!best || ethers.BigNumber.from(r.out).gt(ethers.BigNumber.from(best.out))) best = r
    }
    if (!best || best.out === '0') {
      return null
    }

    return {
      path: best.c.path,
      stableFlags: best.c.stableFlags,
      pairs: best.c.pairs,
      inputAmountRaw: amountInRaw,
      outputAmountRaw: best.out,
    }
  } catch (error) {
    console.error('V2 quote error:', error)
    return null
  }
}

// Simple in-memory cache for V3 quotes
const v3QuoteCache = new Map<string, { result: V3Quote | null; timestamp: number }>()
const CACHE_TTL_MS = 15000 // 15 seconds

// Helper to create exact cache key (no rounding)
function createV3CacheKey(params: V3QuoteParams): string {
  return `${params.tokenIn.toLowerCase()}-${params.tokenOut.toLowerCase()}-${params.amountSpecified}-${params.tradeType}`
}

// Helper to clean expired cache entries
function cleanExpiredCache() {
  const now = Date.now()
  for (const [key, entry] of v3QuoteCache.entries()) {
    if (now - entry.timestamp > CACHE_TTL_MS) {
      v3QuoteCache.delete(key)
    }
  }
}

// V3 Quote Logic
export async function getV3Quote(params: V3QuoteParams): Promise<V3Quote | null> {
  const { tokenIn, tokenOut, inputAmount, amountSpecified, tradeType, v3Pools, quoterContract, multicallContract, mixedQuoterContract, chainId } = params
  
  // Check cache first
  const cacheKey = createV3CacheKey(params)
  cleanExpiredCache()
  
  const cached = v3QuoteCache.get(cacheKey)
  if (cached && (Date.now() - cached.timestamp) < CACHE_TTL_MS) {
    routingLog('Cache hit for amount', amountSpecified)
    return cached.result
  }
  
  try {
    routingLog('Start V3 quote', { tokenIn, tokenOut, tradeType, amountSpecified })
    // Filter to direct pools for this token pair
    const tokenInLower = tokenIn.toLowerCase()
    const tokenOutLower = tokenOut.toLowerCase()

    const directV3Pools = v3Pools.filter((pool) => {
      const token0Lower = pool.token0.id.toLowerCase()
      const token1Lower = pool.token1.id.toLowerCase()
      return (
        (token0Lower === tokenInLower && token1Lower === tokenOutLower) ||
        (token0Lower === tokenOutLower && token1Lower === tokenInLower)
      )
    })

    routingLog('Direct V3 pools count', directV3Pools.length)
    // Build direct quotes (single-hop) if any
    const availableTickSpacings = [...new Set(directV3Pools.map((pool) => pool.tickSpacing))]
    routingLog('Direct tickSpacings', availableTickSpacings)
    const calls = availableTickSpacings.map((tickSpacing) => {
      const tsNum = parseInt(tickSpacing as any)
      if (tradeType === TradeType.EXACT_INPUT) {
        const pathFwd = encodeV3PathTickSpacing([tokenInLower, tokenOutLower], [tsNum])
        const callData = quoterContract.interface.encodeFunctionData('quoteExactInput', [
          pathFwd,
          inputAmount.quotient.toString(),
        ])
        return { target: quoterContract.address, callData }
      } else {
        // exact output uses reverse path
        const pathRev = encodeV3PathTickSpacing([tokenOutLower, tokenInLower], [tsNum])
        const callData = quoterContract.interface.encodeFunctionData('quoteExactOutput', [
          pathRev,
          amountSpecified,
        ])
        return { target: quoterContract.address, callData }
      }
    })

    let directResults: any[] = []
    if (calls.length > 0) {
      try {
        const timeoutPromise = new Promise((_, reject) => setTimeout(() => reject(new Error('Multicall timeout after 30 seconds')), 30000))
        const multicallPromise = multicallContract.callStatic.tryAggregate(false, calls)
        directResults = (await Promise.race([multicallPromise, timeoutPromise])) as any[]
      } catch (e) {
        routingError('V3 direct multicall failed', e)
      }
    }

    let bestDirectQuote: any = null
    let bestDirectFee = 0
    let bestDirectTickSpacing = 0
    const processedDirect = directResults.map((callResult: any, i: number) => {
      const tickSpacing = availableTickSpacings[i]
      const fee = (TICK_SPACING_TO_FEE as any)[parseInt(tickSpacing)] ?? 3000
      if (!fee || !callResult?.success) return null
      try {
        const decoded =
          tradeType === TradeType.EXACT_INPUT
            ? quoterContract.interface.decodeFunctionResult('quoteExactInput', callResult.returnData)
            : quoterContract.interface.decodeFunctionResult('quoteExactOutput', callResult.returnData)
        // decoded[0] is amountOut for EI, amountIn for EO
        return { result: decoded, fee, tickSpacing }
      } catch (err) {
        routingWarn('Failed to decode direct quote', { tickSpacing, err })
        return null
      }
    })
    for (const q of processedDirect) {
      if (!q) continue
      if (tradeType === TradeType.EXACT_INPUT) {
        if (!bestDirectQuote || q.result.amountOut.gt(bestDirectQuote.amountOut)) {
          bestDirectQuote = q.result
          bestDirectFee = q.fee
          bestDirectTickSpacing = parseInt(q.tickSpacing)
        }
      } else {
        if (!bestDirectQuote || q.result.amountIn.lt(bestDirectQuote.amountIn)) {
          bestDirectQuote = q.result
          bestDirectFee = q.fee
          bestDirectTickSpacing = parseInt(q.tickSpacing)
        }
      }
    }

    // Compute and quote multi-hop candidates (2-hop cap)
    let bestMultiHop: { amountOut?: any; amountIn?: any; path: string[]; fees: number[]; tickSpacings?: number[] } | null = null
    const candidates = buildV3TwoHopCandidates({ v3Pools, tokenIn: tokenInLower, tokenOut: tokenOutLower, chainId })
    routingLog('Two-hop candidates', candidates)

    if (candidates.length > 0) {
      if (tradeType === TradeType.EXACT_INPUT) {
        // Multicall all multi-hop exact input quotes using QuoterV2 (path bytes)
        const mhCalls = candidates.map((c) => {
          const encodedPath = encodeV3PathTickSpacing(c.path, c.tickSpacings)
          const cd = quoterContract.interface.encodeFunctionData('quoteExactInput', [encodedPath, inputAmount.quotient.toString()])
          return { target: quoterContract.address, callData: cd }
        })
        try {
          const timeoutPromise = new Promise((_, reject) => setTimeout(() => reject(new Error('Multicall timeout after 30 seconds')), 30000))
          const multicallPromise = multicallContract.callStatic.tryAggregate(false, mhCalls)
          const mhResults = (await Promise.race([multicallPromise, timeoutPromise])) as any[]
          mhResults.forEach((r: any, i: number) => {
            if (!r?.success) return
            try {
              const decoded = quoterContract.interface.decodeFunctionResult('quoteExactInput', r.returnData)
              const amountOut = decoded[0]
              routingLog('Multi-hop EI quote', { path: candidates[i].path, fees: candidates[i].fees, amountOut: amountOut.toString() })
              if (amountOut && !amountOut.isZero() && (!bestMultiHop || amountOut.gt(bestMultiHop.amountOut))) {
                bestMultiHop = { amountOut, path: candidates[i].path, fees: candidates[i].fees, tickSpacings: candidates[i].tickSpacings }
              }
            } catch {}
          })
        } catch (e) {
          routingError('V3 multi-hop exact input failed', e)
        }
      } else if (tradeType === TradeType.EXACT_OUTPUT) {
        // Multicall all multi-hop exact output quotes using QuoterV2 with reverse path
        const mhCalls = candidates.map((c) => {
          const revPath = encodeV3PathTickSpacing([...c.path].reverse(), [...c.tickSpacings].reverse())
          const cd = quoterContract.interface.encodeFunctionData('quoteExactOutput', [revPath, amountSpecified])
          return { target: quoterContract.address, callData: cd }
        })
        try {
          const timeoutPromise = new Promise((_, reject) => setTimeout(() => reject(new Error('Multicall timeout after 30 seconds')), 30000))
          const multicallPromise = multicallContract.callStatic.tryAggregate(false, mhCalls)
          const mhResults = (await Promise.race([multicallPromise, timeoutPromise])) as any[]
          mhResults.forEach((r: any, i: number) => {
            if (!r?.success) return
            try {
              const decoded = quoterContract.interface.decodeFunctionResult('quoteExactOutput', r.returnData)
              const amountIn = decoded[0]
              routingLog('Multi-hop EO quote', { path: candidates[i].path, fees: candidates[i].fees, amountIn: amountIn.toString(), amountOut: amountSpecified })
              if (amountIn && (!bestMultiHop || amountIn.lt(bestMultiHop.amountIn))) {
                bestMultiHop = { amountIn, path: candidates[i].path, fees: candidates[i].fees, tickSpacings: candidates[i].tickSpacings }
              }
            } catch {}
          })
        } catch (e) {
          routingError('V3 multi-hop exact output failed', e)
        }
      }
    }

    // Choose best between direct and multi-hop
    let quoteResult: V3Quote | null = null
    if (tradeType === TradeType.EXACT_INPUT) {
      const directOut = bestDirectQuote?.amountOut
      const multiOut = bestMultiHop?.amountOut
      if (multiOut && !multiOut.isZero() && (!directOut || multiOut.gt(directOut))) {
        routingLog('Selected best route: multi-hop (EXACT_INPUT)', { path: bestMultiHop!.path, fees: bestMultiHop!.fees, amountOut: multiOut.toString() })
        quoteResult = {
          amountOut: multiOut.toString(),
          amountIn: inputAmount.quotient.toString(),
          fee: 0,
          tickSpacing: 0,
          tokenIn: params.currencyIn,
          tokenOut: params.currencyOut,
          gasEstimate: '200000',
          path: bestMultiHop!.path,
          fees: bestMultiHop!.fees,
          tickSpacings: bestMultiHop!.tickSpacings,
        }
      } else if (bestDirectQuote && !bestDirectQuote.amountOut.isZero()) {
        routingLog('Selected best route: direct (EXACT_INPUT)', { tickSpacing: bestDirectTickSpacing, fee: bestDirectFee, amountOut: bestDirectQuote.amountOut.toString() })
        quoteResult = {
          amountOut: bestDirectQuote.amountOut.toString(),
          amountIn: inputAmount.quotient.toString(),
          fee: bestDirectFee,
          tickSpacing: bestDirectTickSpacing,
          tokenIn: params.currencyIn,
          tokenOut: params.currencyOut,
          gasEstimate: bestDirectQuote.gasEstimate?.toString() || '200000',
        }
      }
    } else {
      const directIn = bestDirectQuote?.amountIn
      const multiIn = bestMultiHop?.amountIn
      if (multiIn && (!directIn || multiIn.lt(directIn))) {
        routingLog('Selected best route: multi-hop (EXACT_OUTPUT)', { path: bestMultiHop!.path, fees: bestMultiHop!.fees, amountIn: multiIn.toString(), amountOut: amountSpecified })
        quoteResult = {
          amountOut: amountSpecified,
          amountIn: multiIn.toString(),
          fee: 0,
          tickSpacing: 0,
          tokenIn: params.currencyIn,
          tokenOut: params.currencyOut,
          gasEstimate: '200000',
          path: bestMultiHop!.path,
          fees: bestMultiHop!.fees,
          tickSpacings: bestMultiHop!.tickSpacings,
        }
      } else if (bestDirectQuote) {
        routingLog('Selected best route: direct (EXACT_OUTPUT)', { tickSpacing: bestDirectTickSpacing, fee: bestDirectFee, amountIn: bestDirectQuote.amountIn.toString(), amountOut: amountSpecified })
        quoteResult = {
          amountOut: amountSpecified,
          amountIn: bestDirectQuote.amountIn.toString(),
          fee: bestDirectFee,
          tickSpacing: bestDirectTickSpacing,
          tokenIn: params.currencyIn,
          tokenOut: params.currencyOut,
          gasEstimate: bestDirectQuote.gasEstimate?.toString() || '200000',
        }
      }
    }

    if (!quoteResult) {
      routingWarn('No V3 quote found (neither direct nor multi-hop)')
      v3QuoteCache.set(cacheKey, { result: null, timestamp: Date.now() })
      return null
    }

    routingLog('Final V3 quote', quoteResult)
    v3QuoteCache.set(cacheKey, { result: quoteResult, timestamp: Date.now() })
    return quoteResult

  } catch (error) {
    routingError('V3 quote error', error)
    v3QuoteCache.set(cacheKey, { result: null, timestamp: Date.now() })
    return null
  }
}

// Build 2-hop V3 candidates using topology and prioritized bases
function buildV3TwoHopCandidates({ v3Pools, tokenIn, tokenOut, chainId }: { v3Pools: any[]; tokenIn: string; tokenOut: string; chainId?: number }) {
  const pools = Array.isArray(v3Pools) ? v3Pools : []
  const inLower = tokenIn.toLowerCase()
  const outLower = tokenOut.toLowerCase()

  const neighbors = new Map<string, Set<string>>()
  const poolsByPair = new Map<string, any[]>()

  function addNeighbor(a: string, b: string) {
    const s = neighbors.get(a) || new Set<string>()
    s.add(b)
    neighbors.set(a, s)
  }

  for (const p of pools) {
    try {
      const a = p.token0.id.toLowerCase()
      const b = p.token1.id.toLowerCase()
      addNeighbor(a, b)
      addNeighbor(b, a)
      const key = a < b ? `${a}-${b}` : `${b}-${a}`
      const list = poolsByPair.get(key) || []
      list.push(p)
      poolsByPair.set(key, list)
    } catch {}
  }

  const neighIn = neighbors.get(inLower) || new Set<string>()
  const neighOut = neighbors.get(outLower) || new Set<string>()
  const common = new Set<string>()
  for (const n of neighIn) if (neighOut.has(n)) common.add(n)
  for (const base of getCommonIntermediaries(chainId)) if (neighIn.has(base) && neighOut.has(base)) common.add(base)

  function bestPoolFor(a: string, b: string): { tickSpacing: number; fee: number } | null {
    const key = a < b ? `${a}-${b}` : `${b}-${a}`
    const cands = poolsByPair.get(key) || []
    if (cands.length === 0) return null
    let best: any | null = null
    for (const c of cands) {
      if (!best || parseFloat(c.totalValueLockedUSD || '0') > parseFloat(best.totalValueLockedUSD || '0')) best = c
    }
    if (!best) return null
    const ts = parseInt(best.tickSpacing)
    const fee = (TICK_SPACING_TO_FEE as any)[ts] ?? 3000
    return { tickSpacing: ts, fee }
  }

  const routes: { path: string[]; tickSpacings: number[]; fees: number[] }[] = []
  for (const mid of common) {
    if (mid === inLower || mid === outLower) continue
    const hop1 = bestPoolFor(inLower, mid)
    const hop2 = bestPoolFor(mid, outLower)
    if (!hop1 || !hop2) continue
    routes.push({ path: [inLower, mid, outLower], tickSpacings: [hop1.tickSpacing, hop2.tickSpacing], fees: [hop1.fee, hop2.fee] })
  }
  return routes
}

function encodeV3PathTickSpacing(path: string[], tickSpacings: number[]): string {
  if (!Array.isArray(path) || path.length < 2) throw new Error('encodeV3Path: invalid path')
  if (!Array.isArray(tickSpacings) || tickSpacings.length !== path.length - 1)
    throw new Error('encodeV3Path: tickSpacings length mismatch')
  const parts: string[] = []
  parts.push(path[0].toLowerCase().replace(/^0x/, ''))
  for (let i = 0; i < tickSpacings.length; i++) {
    parts.push(tickSpacings[i].toString(16).padStart(6, '0'))
    parts.push(path[i + 1].toLowerCase().replace(/^0x/, ''))
  }
  return '0x' + parts.join('')
}

// Trade Comparison Logic
export function compareTrades(
  v2Trade: V2Trade<Currency, Currency, TradeType> | V2OnchainBestRoute | null,
  v3Quote: V3Quote | null,
  tradeType: TradeType,
  currencyIn: Currency,
  currencyOut: Currency
): TradeComparisonResult {
  if (!v2Trade && !v3Quote) {
    return { isV3Selected: false, bestV2Trade: null, bestV3Quote: null }
  }
  
  // If only one exists, pick it
  if (!v2Trade) {
    return { isV3Selected: true, bestV2Trade: null, bestV3Quote: v3Quote }
  }
  if (!v3Quote) {
    return { isV3Selected: false, bestV2Trade: v2Trade as any, bestV3Quote: null }
  }

  // Both exist - choose best by trade type
  if (tradeType === TradeType.EXACT_INPUT) {
    const v2Out = 'outputAmount' in (v2Trade as any)
      ? (v2Trade as V2Trade<Currency, Currency, TradeType>).outputAmount
      : CurrencyAmount.fromRawAmount(currencyOut, (v2Trade as V2OnchainBestRoute).outputAmountRaw)
    const v3Out = CurrencyAmount.fromRawAmount(currencyOut, v3Quote.amountOut)
    const isV3Better = v3Out.greaterThan(v2Out)
    return { isV3Selected: isV3Better, bestV2Trade: v2Trade as any, bestV3Quote: v3Quote }
  } else {
    const v2In = 'inputAmount' in (v2Trade as any)
      ? (v2Trade as V2Trade<Currency, Currency, TradeType>).inputAmount
      : ('inputAmountRaw' in (v2Trade as V2OnchainBestRoute) && (v2Trade as V2OnchainBestRoute).inputAmountRaw !== undefined
          ? CurrencyAmount.fromRawAmount(currencyIn, (v2Trade as V2OnchainBestRoute).inputAmountRaw)
          : (() => { throw new Error('inputAmountRaw is missing from V2OnchainBestRoute'); })())
    const v3In = CurrencyAmount.fromRawAmount(currencyIn, v3Quote.amountIn)
    const isV3Better = v3In.lessThan(v2In)
    return { isV3Selected: isV3Better, bestV2Trade: v2Trade as any, bestV3Quote: v3Quote }
  }
}

// Trade Object Creation
export function createTradeObject(
  comparison: TradeComparisonResult,
  tradeType: TradeType,
  currencyIn: Currency,
  currencyOut: Currency,
  gasEstimateUSD: string
) {
  const { isV3Selected, bestV2Trade, bestV3Quote } = comparison
  
  
  if (!isV3Selected && bestV2Trade) {
    // Support legacy SDK-based V2Trade and on-chain V2 route
    if ('route' in (bestV2Trade as any)) {
      const legacy = bestV2Trade as V2Trade<Currency, Currency, TradeType>
      const routeParams = {
        v2Routes: [{ routev2: legacy.route, inputAmount: legacy.inputAmount, outputAmount: legacy.outputAmount }],
        v3Routes: [],
        mixedRoutes: [],
        tradeType,
      }
      const trade = new ClassicTrade(routeParams)
      if (!trade.routes || trade.routes.length === 0) {
        trade.routes = routeParams.v2Routes
      }
      // Create a route wrapper that has both 'pairs' and 'pools' for compatibility
      const routeWrapper = {
        ...legacy.route,
        pools: legacy.route.pairs, // Alias pairs as pools for getRoutingDiagramEntries
        protocol: Protocol.V2,
      }

      const finalTrade = {
        ...trade,
        inputAmount: legacy.inputAmount,
        outputAmount: legacy.outputAmount,
        v2Routes: routeParams.v2Routes,
        swaps: [{ route: routeWrapper, inputAmount: legacy.inputAmount, outputAmount: legacy.outputAmount }],
        executionPrice: legacy.executionPrice,
        worstExecutionPrice: function (slippageTolerance: any) {
          return legacy.worstExecutionPrice(slippageTolerance)
        },
        minimumAmountOut: function (slippageTolerance: any) {
          return legacy.minimumAmountOut(slippageTolerance)
        },
        maximumAmountIn: function (slippageTolerance: any) {
          return legacy.maximumAmountIn(slippageTolerance)
        },
        inputTax: (legacy as any).inputTax || new Percent(0),
        outputTax: (legacy as any).outputTax || new Percent(0),
        priceImpact:
          (legacy as any).priceImpact || calculatePriceImpact(currencyIn, currencyOut, legacy.inputAmount, legacy.outputAmount),
        gasUseEstimate: 250000,
        gasUseEstimateUSD: gasEstimateUSD,
        quoteMethod: QuoteMethod.CLIENT_SIDE_FALLBACK,
        approveInfo: { needsApprove: false },
        routing: 'CLASSIC',
      }
      return finalTrade
    } else {
      const v2 = bestV2Trade as unknown as V2OnchainBestRoute
      const inputAmt = CurrencyAmount.fromRawAmount(currencyIn, v2.inputAmountRaw)
      const outputAmt = CurrencyAmount.fromRawAmount(currencyOut, v2.outputAmountRaw)
      const routev2 = new V2Route(v2.pairs, currencyIn, currencyOut)
      const routeParams = {
        v2Routes: [{ routev2, inputAmount: inputAmt, outputAmount: outputAmt }],
        v3Routes: [],
        mixedRoutes: [],
        tradeType,
      }
      const trade = new ClassicTrade(routeParams)

      // Create a route wrapper that has both 'pairs' and 'pools' for compatibility
      const routeWrapper = {
        ...routev2,
        pools: routev2.pairs, // Alias pairs as pools for getRoutingDiagramEntries
        protocol: Protocol.V2,
      }

      const finalTrade = {
        ...trade,
        inputAmount: inputAmt,
        outputAmount: outputAmt,
        v2Routes: routeParams.v2Routes,
        swaps: [{ route: routeWrapper, inputAmount: inputAmt, outputAmount: outputAmt }],
        executionPrice: new Price(currencyIn, currencyOut, inputAmt.quotient.toString(), outputAmt.quotient.toString()),
        worstExecutionPrice: function (slippageTolerance: any) {
          const factor = new Percent(1).subtract(slippageTolerance)
          const worstOut = outputAmt.multiply(factor)
          return new Price(currencyIn, currencyOut, inputAmt.quotient.toString(), worstOut.quotient.toString())
        },
        minimumAmountOut: function (slippageTolerance: any) {
          const factor = new Percent(1).subtract(slippageTolerance)
          return outputAmt.multiply(factor)
        },
        maximumAmountIn: function () {
          return inputAmt
        },
        inputTax: new Percent(0),
        outputTax: new Percent(0),
        priceImpact: calculatePriceImpact(currencyIn, currencyOut, inputAmt, outputAmt),
        gasUseEstimate: 250000,
        gasUseEstimateUSD: gasEstimateUSD,
        quoteMethod: QuoteMethod.CLIENT_SIDE_FALLBACK,
        approveInfo: { needsApprove: false },
        routing: 'CLASSIC',
      }
      return finalTrade as any
    }
  } else if (isV3Selected && bestV3Quote) {
    // Create custom V3 trade object
    
    const v3InputAmount = tradeType === TradeType.EXACT_INPUT ? 
      CurrencyAmount.fromRawAmount(currencyIn, bestV3Quote.amountIn) :
      CurrencyAmount.fromRawAmount(currencyIn, bestV3Quote.amountIn)
    
    const v3OutputAmount = tradeType === TradeType.EXACT_INPUT ?
      CurrencyAmount.fromRawAmount(currencyOut, bestV3Quote.amountOut) :
      CurrencyAmount.fromRawAmount(currencyOut, bestV3Quote.amountOut)
    
    // Create a proper Price object with baseCurrency and quoteCurrency
    const executionPrice = new Price(
      currencyIn,  // baseCurrency
      currencyOut, // quoteCurrency
      v3InputAmount.quotient.toString(),
      v3OutputAmount.quotient.toString()
    )
    
    // Create a mock route for the swaps property
    const mockV3Route = {
      path: [currencyIn, currencyOut],
      pools: [{
        fee: bestV3Quote.fee,
        tickSpacing: bestV3Quote.tickSpacing,
        token0: currencyIn,
        token1: currencyOut
      }],
      protocol: Protocol.V3,
    }

    const finalV3Trade = {
      tradeType,
      inputAmount: v3InputAmount,
      outputAmount: v3OutputAmount,
      executionPrice: executionPrice,
      // Add v3Routes property that transaction handler expects
      v3Routes: [{
        inputAmount: v3InputAmount,
        outputAmount: v3OutputAmount,
        path: [currencyIn, currencyOut], // Direct path for single-hop V3 trades
        pools: [{
          fee: bestV3Quote.fee,
          tickSpacing: bestV3Quote.tickSpacing,
          token0: currencyIn,
          token1: currencyOut
        }]
      }],
      swaps: [{ route: mockV3Route, inputAmount: v3InputAmount, outputAmount: v3OutputAmount }],
      gasUseEstimate: 250000,
      gasUseEstimateUSD: gasEstimateUSD,
      quoteMethod: QuoteMethod.CLIENT_SIDE_FALLBACK,
      approveInfo: { needsApprove: false },
      routing: 'CLASSIC',
      isV3: true, // Flag to identify V3 trades
      v3Quote: bestV3Quote, // Include the raw quote data
      // Add worstExecutionPrice method that trade validation expects
      worstExecutionPrice: function(slippageTolerance: any) {
        // Create a new Price object with slippage-adjusted amounts
        if (tradeType === TradeType.EXACT_INPUT) {
          // For exact input, worst price is lower output
          const slippageFactor = new Percent(1).subtract(slippageTolerance)
          const worstOutputAmount = v3OutputAmount.multiply(slippageFactor)
          return new Price(
            currencyIn,
            currencyOut,
            v3InputAmount.quotient.toString(),
            worstOutputAmount.quotient.toString()
          )
        } else {
          // For exact output, worst price is higher input
          const slippageFactor = new Percent(1).add(slippageTolerance)
          const worstInputAmount = v3InputAmount.multiply(slippageFactor)
          return new Price(
            currencyIn,
            currencyOut,
            worstInputAmount.quotient.toString(),
            v3OutputAmount.quotient.toString()
          )
        }
      },
      // Add missing methods required by analytics
      minimumAmountOut: function(slippageTolerance: any) {
        if (tradeType === TradeType.EXACT_INPUT) {
          // For exact input, minimum output is reduced by slippage
          const slippageFactor = new Percent(1).subtract(slippageTolerance)
          return v3OutputAmount.multiply(slippageFactor)
        } else {
          // For exact output, the output amount is already exact
          return v3OutputAmount
        }
      },
      maximumAmountIn: function(slippageTolerance: any) {
        if (tradeType === TradeType.EXACT_OUTPUT) {
          // For exact output, maximum input is increased by slippage
          const slippageFactor = new Percent(1).add(slippageTolerance)
          return v3InputAmount.multiply(slippageFactor)
        } else {
          // For exact input, the input amount is already exact
          return v3InputAmount
        }
      },
      inputTax: new Percent(0),
      outputTax: new Percent(0),
      // Add priceImpact calculation for V3 trade
      priceImpact: calculatePriceImpact(currencyIn, currencyOut, v3InputAmount, v3OutputAmount),
    } as any
    
    return finalV3Trade
  }
  
  return null
}
